  'settings.reconnect.policyHint': 'تُطلق إعادات الاتصال التلقائية من مكان واحد، وليس هذه الصفحة. تبدأ واحدة حين تطلب خلفية التنزيل نفسها محاولة أخرى بعد مهلة، وهذه طريقة المستضيف في القول إن الحدّ مرتبط بهذا العنوان. ولا تعمل أبدًا والطابور متوقّف، لأن إعادة تشغيل الموجّه تقطع التنزيلات التي ما زالت جارية. ولا تعمل أبدًا ما دامت إعادة الاتصال غير مهيّأة بالكامل. ولا تعمل إلا واحدة في المرة: الطلب الثاني ينتظر حكم الأول بدل أن يتنازع معه على الموجّه. وإن لم يتغيّر العنوان، فلا يُقدَّم شيء، وتُترك مهلة إعادة المحاولة المعتادة تأخذ مجراها.',

