  'settings.access.cardTitle': 'ربط النسخ والوصول عن بُعد',
  'settings.access.phrase.body': 'عبارة واحدة تربط كل نسخ KnightLoader التي تشغّلها. أنشئها هنا، ثم الصقها في نسخك الأخرى. لا تحتاج إلى حساب أو تسجيل دخول، ولا يوجد ما تضبطه.',
  'settings.access.phrase.noPasswordWarning': 'هذه النسخة بلا كلمة مرور. العبارة تصل إلى كل نسخة تربطها بها، فمن يقرأها هنا يصل إليها جميعًا وليس هذه فقط. يُفضّل تعيين كلمة مرور أعلاه أولًا.',
  'settings.access.phrase.activate': 'إنشاء عبارة',
  'settings.access.phrase.howStep1': 'على هذه النسخة، اضغط «{button}». تظهر اثنتا عشرة كلمة.',
  'settings.access.phrase.howStep2': 'افتح KnightLoader على الجهاز الآخر، وانتقل إلى الصفحة نفسها، واضغط «{button}» ثم اكتب الكلمات الاثنتي عشرة.',
  'settings.access.phrase.howStep3': 'تم! تظهر كل نسخة الآن لدى الأخرى تحت «النسخ»، ويمكنك تشغيل أي منهما من أي منهما. ومع تشغيل الترحيل تصبح نسخك قابلة للوصول من خارج شبكتك.',
  'settings.access.phrase.howWhat': 'الكلمات سرّ، وليست عنوانًا. كل نسخة تشتق منها مفتاحين: واحد للعثور على البقية، وآخر للتشفير.\n\nللعثور على بعضها، تتصل كل نسخة من تلقاء نفسها بنفس نقطة اللقاء على الإنترنت. ومن يُظهر المفتاح نفسه يتم وصله. لذلك لا يلزم أن تكون أي من نسخك قابلة للوصول من الخارج.\n\nنقطة اللقاء لا تستطيع القراءة. فهي لا ترى كلماتك أبدًا، وكل ما يمر بها مشفّر بالمفتاح الثاني.',
  'settings.access.phrase.statusDisconnected': 'غير متصل',
