  'settings.torrents.portTitle': 'المنفذ والتوجيه',
  'settings.torrents.port': 'المنفذ',
  'settings.torrents.portHint': 'المنفذ الذي ينصت من خلاله هذا المثيل لاتصالات السرب. 0 يترك محرك التورنت يختار واحدًا بنفسه.',
  'settings.torrents.portRestartHint': 'يبني المحرك عميل التورنت الخاص به مرة واحدة فقط، لذلك لا يسري المنفذ الجديد إلا بعد إعادة تشغيل هذه النسخة. أما طلب توجيهه من الموجّه فينجح فورًا، سواء كان تورنت ينصت عليه بعد أم لا.',
  'settings.torrents.portMapHint': 'يطلب من الموجّه إعادة توجيه المنفذ أعلاه إلى هذا الجهاز عبر UPnP، بحيث يستطيع الأقران خلف موجّه آخر الوصول إليه رغم ذلك. لا يدعم كل موجّه هذا، وبعضها يقبل الطلب دون أن يعمل فعليًا.',
