  'settings.torrents.dhtHint': 'يجد أقرانًا دون أي متعقب، باستخدام عملاء BitTorrent آخرين كدليل موزّع.',
  'settings.torrents.pex': 'تبادل الأقران (PEX)',
  'settings.torrents.pexHint': 'يتبادل الأقران المعروفين مع المتصلين بالفعل، بحيث يوجد السرب ذو الأقران القليلين بسرعة أكبر.',
  'settings.torrents.privateNote': 'التورنت الخاص يعطّل الاثنين تلقائيًا بمجرد معرفة بياناته الوصفية، مهما كان الإعداد هنا: فورًا عند رفع ملف .torrent، أو حالما تصل البيانات الوصفية الخاصة برابط المغناطيس من السرب. معظم المتعقبات الخاصة تحظر الحسابات التي تستخدم أيًا منهما.',
  'container.noJD': 'إنه مشفّر، ولا تفتحه إلا خلفية JDownloader. ولا توجد واحدة مُعدّة: اضبط KL_JD على JDownloader تستطيع هذه النسخة الوصول إليه، ثم أعد التشغيل.',
