  'settings.torrents.notApplied': 'هذا البناء لا يطبّق بعدُ اثنين من الإعدادات أدناه. يُحفظ حد الرفع ويُفحص، لكن المحرك لا يستطيع تطبيقه على تنزيل جارٍ. وكذلك لا يصل DHT وPEX إلى التورنت العادي: فهو يبذر وكلاهما مشغّل، مهما كان الإعداد هنا. أما التورنت الخاص فيعمل بشكل مختلف، كما يشرح الـ(i) بجوار «اكتشاف الأقران».',
  'onboarding.step': 'الخطوة {n} من {total}',
