  'onboarding.back': 'رجوع',
  'onboarding.next': 'التالي',
  'onboarding.finish': 'تم',
  'onboarding.welcome.title': 'مرحبًا بك في KnightLoader',
  'onboarding.welcome.body': 'KnightLoader مدير تنزيلات تستضيفه بنفسك. الصق رابطًا أو أفلته فتجلبه الواجهة الخلفية المناسبة: المحرك المدمج لروابط الملفات العادية، وyt-dlp لصفحات الوسائط، وخدمة debrid للمستضيفين الذين تدفع لهم بالفعل، أو JDownloader بلا واجهة لكل ما عدا ذلك. تعرض هذه الجولة القصيرة الإعداد الوحيد الذي يستحق أن تتحقق منه قبل أن تبدأ.',
  'onboarding.welcome.langLabel': 'لغة الواجهة',
  'onboarding.folder.title': 'أين يجب أن تحطّ الملفات؟',
  'onboarding.folder.body': 'هذا هو المجلد الذي تُكتب فيه التنزيلات المكتملة. اكتب مسارًا أو تصفّح الخادم لاختيار واحد. يمكنك تغييره مرة أخرى في أي وقت من صفحة الإعدادات «عام».',
  'onboarding.accounts.title': 'مضيفون مميّزون، متى ما أردتهم',
  'onboarding.accounts.body': 'يعمل الطابور بلا أي حساب على الإطلاق. وحين تريد السرعة الكاملة لدى مستضيف أو خدمة debrid تدفع لها بالفعل، أضف بيانات الدخول إليها تحت الحسابات. لا شيء من هذا يحتاج إلى إعداد الآن.',
  'onboarding.accounts.link': 'فتح الحسابات',
  'onboarding.finished.title': 'أنت جاهز الآن',
  'onboarding.finished.body': 'بهذا تنتهي الجولة. تحتوي صفحة المساعدة تحت الإعدادات على شرح كامل لكل شيء آخر يقوم به هذا الإصدار، وتحمل معظم عناصر التحكم شرحها الخاص خلف أيقونة (i).',

