  'settings.nav.shortcuts': 'الاختصارات',
  'settings.shortcuts.subtitle': 'كل أمر يأتي باختصار لوحة مفاتيح افتراضي، مجمّعًا حسب مكان استخدامه. غيّر ربطًا، أو أعد ضبطه إلى افتراضيّه.',
  'settings.shortcuts.empty': 'لا أوامر لها اختصار افتراضي بعد.',
  'settings.shortcuts.change': 'تغيير',
  'settings.shortcuts.reset': 'إعادة ضبط',
