  'settings.downloads.diskHint': 'ثلاثة أرقام تحتجز التنزيلات قبل أن يمتلئ القرص. والثلاثة كلها بايتات حرة على وحدة التخزين التي يُكتب عليها التنزيل، فمجلد العمل الموجود على قرص آخر يُقاس على ذلك القرص. والصفر يطفئ الرقم المعني. ليس كل نظام يمكن سؤاله كم بقي من مساحة حرة، وحيث لا يتوفر الجواب لا يُحتجَز شيء أبدًا، لأن حارسًا يحجب حين لا يعرف كان سيوقف جهازًا سليمًا تمامًا.',
