  'settings.rules.action.category': 'الفئة',
  'settings.rules.action.categoryHint': 'يودع الروابط المطابقة في أحد الأدراج من قائمة الفئات في أسفل هذه الصفحة، والدرج يجلب معه مجلده وموضعه في الطابور ومفتاح فك الضغط وقاعدة التعارض الخاصة به. وإن تُرك كما هو، فلا قاعدة لها رأي في ذلك ويبقى الرابط غير مودَع. وإن سمّت هذه القاعدة مجلد تنزيل أيضًا، فاز ذلك المجلد وظلّ الدرج يقدّم كل ما عداه. وتسمية درج محذوف تُرفض عند الحفظ، لأن قاعدة تشير إلى درج غير موجود لا تفعل شيئًا إطلاقًا مع كل رابط تطابقه، وبلا أي رسالة.',
