  'detail.onDisk': 'على القرص الآن',
  'detail.onDiskHint': 'ما يبلغه الملف على القرص في هذه الثانية، يُسأل عنه الخادم بدل أن يُحسب هنا. والتنزيل الجاري يكبر بين نظرة وأخرى، وهذا ليس الحجم الذي أعلنه المستضيف.',
  'detail.mirrorOf': 'نسخة مركونة لـ',
  'detail.times': 'الطوابع الزمنية',
  'detail.timesHint': 'متى وصل هذا الرابط، ومتى تغيّر آخر مرة، ومتى استقرّ. ولا وقت هنا لبدء النقل: التطبيق لم يسجّله قط، وتخمينه من الثلاثة الأخرى سيكون رقمًا يبني الناس عليه تصرفهم.',
  'detail.nextTry': 'المحاولة التالية',
  'detail.stalledSince': 'واقف منذ',
  'detail.retries': 'الإعادات حتى الآن',
  'detail.retriesHint': 'كم مرة أُعيدت محاولة هذا التنزيل بعد فشل. ويعود العدّاد إلى الصفر لحظة انتهاء التنزيل، فالصف المنتهي يعرض صفرًا ولو استغرق أربعة أشواط. وكم بقي من محاولات لا يظهر هنا: السقف يتوقف على السبب وعلى المستضيف، وهذه الصفحة لا تستطيع حسابه.',
  'detail.stallRestarts': 'إعادات البدء بعد الوقوف',
  'detail.stallRestartsHint': 'كم مرة أعادت مراقبة التوقف عن التقدّم بدء هذا التنزيل من تلقاء نفسها. ويعود العدّاد إلى الصفر عند انتهاء التنزيل، تمامًا كالعدّاد أعلاه.',
  'detail.failure': 'ما الذي أخفق',
  'detail.cause': 'السبب',
  'detail.message': 'ما قالته الخلفية',
  'detail.messageHint': 'الجملة الآتية مما حاول جلب هذا، حرفيًا وبلا ترجمة. وهي الفشل الحالي لا غير: إعادة البدء تمحوها، ولا يُحتفظ بشيء من سابقاتها.',
  'detail.heldBack': 'ما يحتجزه',
  'detail.doing': 'ما يفعله الآن',
  'detail.filtered': 'محتجَز من مرشّح الروابط',
  'detail.gaveUp': 'لا محاولة أخرى',
  'detail.gaveUpHint': 'هنا توقّف عن قصد، لا لأن المحاولات نفدت: كابتشا، أو قرص ممتلئ، أو قاعدة تقول «أبدًا» لهذا المستضيف. ورفع عدد الإعادات لا يغيّر في هذا شيئًا. والعلامة نفسها لا تُكتب في قاعدة البيانات، فهي تزول بعد إعادة التشغيل، وإن بقي سببها.',
  'detail.rules': 'القواعد التي شكّلت هذا',
  'detail.rulesHint': 'القواعد التي انطبقت على هذا الرابط لحظة تجهيزه، بترتيب انطباقها. وهي محفوظة بالاسم، فالقاعدة التي أُعيدت تسميتها بعد ذلك لا تُوجَد بعد الآن، والقاعدة التي لم يكن لها اسم محفوظة بالموضع الذي كان لها آنذاك. والنقر على واحدة يفتحها في محرر القواعد.',
  'detail.openRule': 'افتح في محرر القواعد',
  'detail.noRules': 'لم تمسّ أي قاعدة هذا الرابط.',
  'detail.player': 'التشغيل',
  'detail.play': 'شغّله هنا',
  'detail.playHint': 'يشغّل الملف مباشرة من هذه النسخة، دون تنزيله مرة ثانية. ولا يُجلب شيء قبل أن تضغط زر التشغيل، ويبقى الملف مكانه.',
  'detail.playPartial': 'هذا التنزيل لم يكتمل. ولا يُشغَّل منه إلا الجزء الموجود سلفًا على القرص، والقفز إلى ما بعده لا يعمل، وبعض الملفات لا تشغّل شيئًا البتة قبل وصول آخر بايت.',
  'detail.playUnsupported': 'هذا المتصفّح لا يستطيع تشغيل هذا الملف. افتحه أو احفظه من قائمة النقر الأيمن بدل ذلك.',
  'detail.playRemote': 'لا يُشغَّل هنا إلا ما كان على هذه النسخة. فالنسخة الأخرى تسلّم ملفاتها قطعةً واحدة وبلا قفز، وهذا ما لا يستطيع مشغّل أن يعمل به.',
  'detail.playNotLocal': 'هذا التنزيل جلبه JDownloader، فالملف يقيم على قرص تلك العملية لا على هذا القرص.',
  'detail.playNoFile': 'لا يوجد على القرص شيء لتشغيله بعد.',
