  'views.deleteConfirm': 'احذف العرض',
  'views.clearAll': 'امسح البحث وكل المرشّحات',
  'views.clearAllHint': 'يبقى البحث والمرشّحات مضبوطة حين تغادر هذه الصفحة وتعود، فترى القائمة نفسها التي تركتها. وهذا يعيد القائمة كاملة. أما العروض المحفوظة فتبقى كما هي.',

  'disk.title': 'مجلدات الوجهة',
  'disk.hint': 'المساحة الحرة والمستخدمة على كل مجلد يمكن أن ينتهي فيه تنزيل، وكم بقي على الطابور أن يكتبه في كل منها. والأرقام تأتي من الاستدعاء نفسه الذي تُفحص به حدود القرص، وعمرها ثوانٍ قليلة على الأكثر. والحرة والمستخدمة لا يساوي مجموعهما دائمًا حجم وحدة التخزين: نظام الملفات يحجز جزءًا للنظام، وحصة المستخدم قد تترك لهذه النسخة أقل مما لدى وحدة التخزين فعلًا. والمجلدان الموجودان على القرص نفسه يعرض كل منهما ذلك القرص، فلا تجمع الصفوف أبدًا.',
  'disk.free': 'المساحة الحرة',
  'disk.used': 'المساحة المستخدمة',
  'disk.size': 'حجم القرص',
  'disk.queued': 'ما بقي كتابته',
  'disk.queuedHint': 'ما ستضيفه إلى هذا المجلد التنزيلات المستحقة بعد: الحجم الذي أعلنه المستضيف ناقص ما وصل سلفًا. والتنزيل الذي لا يفصح المستضيف عن حجمه يُحسب هنا صفرًا، فهذا حدّ أدنى لا وعد، ولهذا قد يظهر مجلد بلا بايتات إلى جانب صف من التنزيلات. والتنزيلات التي أطفأتها تبقى خارج الحساب، وهي القاعدة نفسها التي تتبعها العدّادات تحت القائمة. والتنزيل الجاري سلفًا يكون مكانه على القرص قد حُجز غالبًا لحظة بدئه، فبايتاته ناقصة أصلًا من المساحة الحرة المجاورة، ولا تأتي فوقها.',
  'disk.tasks': '{n} تنزيل',
  'disk.unknown': 'هذا النظام لا يبلّغ عن المساحة الحرة',
  'disk.unknownHint': 'ليست كل نواة يمكن سؤالها كم بقي في وحدة التخزين من مساحة، وهذا البناء لا يملك استدعاءً للنواة التي يعمل عليها. وحيث يغيب الجواب لا يُحتجَز شيء: تبدأ التنزيلات كأنه لا يوجد حد للقرص. وهذا السطر موجود كي تميّز ذلك عن قرص ممتلئ فعلًا.',
  'disk.missing': 'لم يُنشأ بعد',
  'disk.missingHint': 'هذا المجلد يُنشئه من يكتب فيه أول ملف، فهو غير موجود بعد. والأرقام تصف {path}، أقرب مجلد موجود فوقه، وهو يقع على القرص الذي سيحطّ عليه التنزيل.',
  'disk.measured': 'مقيس عند {path}',
  'disk.elsewhereHint': 'المجلد نفسه تعذّر قياسه، فالمقيس هو أقرب مجلد فوقه أمكن قياسه. وإن لم تُركَّب إحدى نقاط الوصل، فقد يكون هذا قرصًا مختلفًا تمامًا عن القرص المقصود للتنزيل. انظر إلى المسار قبل أن تستنتج شيئًا من الأرقام.',
  'disk.sampled': 'قُرئ قبل {n} ثانية',
  'disk.tight': 'الطابور لا يتّسع',
  'disk.tightHint': 'المستحق لهذا المجلد أكثر مما بقي حرًّا على القرص. وهذا السطر وحده لا يوقف شيئًا: الاحتجاز يجري واحدًا واحدًا حين يأتي دور التنزيل، بالأرقام الموجودة في صفحة إعدادات التنزيلات، والتنزيل الذي لا يعرف أحد حجمه لا يُحسب هنا أصلًا.',
  'disk.truncated': 'ليس كل مجلد مذكورًا هنا',
  'disk.truncatedHint': 'الطابور يقصد من المجلدات خارج المضبوطة أكثر مما يستحق القياس عند كل قراءة، فتُركت خارج القائمة المجلداتُ الأقل استحقاقًا. أما كل مجلد ضبطته أنت فهو حاضر دائمًا.',
  'disk.markLow': 'تحت هذا لا يبدأ شيء جديد',
  'disk.markStop': 'تحت هذا يتوقف كل شيء',
  'disk.limits': 'اضبط حدود القرص',
  'disk.stripLabel': 'المساحة عند مجلدات الوجهة',
  'disk.role.downloads': 'مجلد التنزيل',
  'disk.role.category': 'مجلد الفئة',
  'disk.role.work': 'مجلد العمل',
  'disk.role.task': 'مضبوط على التنزيل نفسه',

  'settings.volume.title': 'سقف حجم البيانات',
  'settings.volume.titleHint': 'ما أنهت هذه النسخة تنزيله، محسوبًا مقابل سقف تضبطه أنت، لكل فترة. ويُحسب الحجم الذي أعلنه المستضيف لكل تنزيل منتهٍ، فما انتهى بلا حجم معلن يُحسب صفرًا، وما يرفعه تورنت لا يُحسب البتة. وهذه قراءة لتنزيلاتك لا قياس لخطك: لا شيء هنا يرى البايتات التي حرّكها موجّهك فعلًا.',
  'settings.volume.cap': 'السقف لكل فترة (GB)',
  'settings.volume.capHint': '0 يعني بلا سقف: يظل العدّاد يعمل ولا يُحتجَز شيء أبدًا. والغيغابايت هنا عشرية، كما يذكر المزوّد حصتك، فـ500 GB هي 500 000 000 000 بايت لا 465 GiB. أما قيم القرص أعلى هذه الصفحة فهي GiB ثنائية، وهي وحدة أخرى لسؤال آخر.',
  'settings.volume.resetDay': 'العدّاد يبدأ من جديد يوم',
  'settings.volume.resetDayHint': 'يوم الشهر الذي يعود فيه العدّاد إلى الصفر، وهو عادةً اليوم الذي تتجدد فيه حصتك. وفي شهر أقصر من اليوم الذي اخترته، يبدأ من جديد في آخر يوم من ذلك الشهر ولا ينزلق إلى الشهر التالي أبدًا. والحساب بساعة الخادم لا بساعة متصفّحك، لأن الخادم هو الذي يحتجز الطابور.',
  'settings.volume.action': 'عند بلوغ السقف',
  'settings.volume.actionHint': 'النقل الجاري سلفًا لا يُقطع أبدًا مهما اخترت: القطع في وسط الملف يرمي بايتات أنفقتها. «أخبرني فقط» لا يغيّر شيئًا، فيبقى العدّاد هو الميزة كلها. و«لا تبدأ تنزيلات جديدة» يترك ما يعمل يكتمل ويحتجز الطابور حتى يبدأ العدّاد من جديد، وكل صف منتظر يقول ذلك. و«أبطئ كل شيء» يبقي الطابور يعمل بالسرعة أدناه.',
  'settings.volume.actionReport': 'أخبرني فقط',
  'settings.volume.actionPause': 'لا تبدأ تنزيلات جديدة',
  'settings.volume.actionThrottle': 'أبطئ كل شيء',
  'settings.volume.throttle': 'السرعة بعد بلوغ السقف',
  'settings.volume.throttleHint': 'الحد الذي يسري بقية الفترة. وهو سقف إلى جانب حدودك الأخرى لا بديل عنها، فالنافذة الليلية أو مفتاح الهدوء إن طلبا أقل فازا. و0 هنا يعني بلا حد إطلاقًا، وهو نفسه ألا يكون هناك سقف، فأصغر رقم مفيد هو 1.',
  'settings.volume.noCap': 'بلا سقف',
  'settings.volume.used': 'المُنزَّل في هذه الفترة',
  'settings.volume.usedOf': '{used} من {cap}',
  'settings.volume.resetsOn': 'يبدأ من جديد في {date}',
