  'failure.raw': 'ما قالته الخلفية',
  'failure.rawHint': 'السطر الذي أخرجته الأداة نفسها، دون تغيير وبالإنجليزية. ينفع حين تبحث عنه أو تبلّغ به في مكان ما. والجملة أعلاه هي قراءة هذا التطبيق له.',
  'failure.nothingToDo': 'ليس في KnightLoader ما يغيّر هذه الحالة.',
  'failure.close': 'إغلاق',
  'failure.botCheck.line': 'الموقع يريد جلسة مسجَّلة الدخول قبل أن يسلّم الفيديو.',
  'failure.botCheck.hint': 'الانتظار أو التنزيل الأبطأ أو هوية متصفح أخرى لا تغيّر شيئًا هنا. الكوكيز من متصفح أنت مسجَّل الدخول فيه فعلًا هي وحدها ما ينفع. صدّر ملف cookies.txt الخاص بالموقع من ذلك المتصفح وألصقه هنا: يُحفظ في مخزن بيانات الاعتماد المشفَّر، ويُسلَّم إلى yt-dlp ملفًا لا يقرأه إلا هذا الخادم، ويُحذف من جديد لحظة انتهاء التنزيل.',
  'failure.botCheck.action': 'حفظ كوكيز لهذا الموقع',
  'failure.membersOnly.line': 'للأعضاء فقط، والتنزيل وصل بلا عضوية.',
  'failure.membersOnly.hint': 'يصل yt-dlp بصفة من تقوله الكوكيز المحفوظة. سجّل الدخول بالحساب الذي يحمل العضوية، وصدّر من ذلك المتصفح ملف cookies.txt الخاص بالموقع وألصقه هنا. وبلا عضوية على ذلك الحساب لا يغيّر شيء هنا الجواب.',
  'failure.membersOnly.action': 'حفظ كوكيز لهذا الموقع',
  'failure.geoBlocked.line': 'الموقع لا يقدّم هذا الفيديو لهذه المنطقة.',
  'failure.geoBlocked.hint': 'الكوكيز لا تنفع، فالمحجوب هو العنوان لا الحساب. ولا يستطيع KnightLoader أن يمرّر تنزيل yt-dlp عبر أحد اتصالاته المسمّاة، لأن yt-dlp يعمل كعملية مستقلة ويأخذ وكيله من البيئة التي بدأ فيها هذا الخادم. فالحل خارج هذه النافذة: شغّل الخادم خلف VPN، أو اضبط له HTTP_PROXY وHTTPS_PROXY.',
  'failure.gone.line': 'المصدر يقول إن هذا لم يعد موجودًا.',
  'failure.gone.hint': 'محذوف عند المصدر أو مُزال أو صار خاصًا. لا حساب ولا محاولة جديدة تعيده، وكل محاولة أخرى لا تفعل غير أن تجعل المستضيف يكرر الجواب نفسه. وإزالة الرابط ترفع الصف من القائمة، وما نُزِّل سلفًا يبقى على القرص.',
  'failure.gone.action': 'إزالة هذا الرابط',
  'failure.drm.line': 'هذا الفيديو مشفَّر، وyt-dlp لا يفكّ تشفيره.',
  'failure.drm.hint': 'DRM ليس حاجزًا يتجاوزه تسجيل دخول أو عنوان آخر: البيانات تصل مشفَّرة، والمفتاح لا يذهب إلا إلى مشغّل يثق به الموقع. ولا شيء يُضبط من أجله. أما بقية صفوف الرابط نفسه، الصورة المصغّرة والوصف والترجمات، فغالبًا لا يمسّها هذا ويمكن أن تبقى.',
  'failure.drm.action': 'إزالة هذا الرابط',
  'failure.extractorBroken.line': 'الموقع تغيّر، وyt-dlp في هذا البناء لم يعد يُخرج الفيديو.',
  'failure.extractorBroken.hint': 'yt-dlp قال ذلك بنفسه: لم يستطع قراءة الصفحة وطلب تقرير خلل. وفي الغالب نقل الموقع شيئًا من مكانه، وyt-dlp أحدث يتدبّر أمره من جديد خلال أيام. وyt-dlp يأتي داخل صورة KnightLoader، فالطريق إلى نسخة أحدث هو صورة أحدث لا زر هنا في الداخل: هذا الخادم لا يُسمح له باستبداله، ولا مكان لديه في الحاوية يضع فيه نسخة جديدة.',
  'cookies.title': 'كوكيز {host}',
  'cookies.addTitle': 'حفظ كوكيز لموقع',
  'cookies.add': 'إضافة موقع',
  'cookies.save': 'حفظ وإعادة المحاولة',
  'cookies.saved': 'حُفظت الكوكيز.',
  'cookies.hostHint': 'يُبحث عن الملف بهذا المستضيف وبكل نطاق فوقه، من الأخصّ إلى الأعمّ، فالملف المحفوظ تحت youtube.com هو نفسه الذي يستعمله رابط من music.youtube.com. والخادم يكتب الاسم بأحرف صغيرة، ويحذف www. من المقدمة، ويردّ العنوان الملصوق كاملًا إلى الموقع نفسه، فقد تسمّيه القائمة على نحو يختلف قليلًا عمّا كتبته أنت.',
  'cookies.jarHint': 'ألصق ما يعطيك إياه مُصدِّر الكوكيز، بصيغة Netscape، بأسطر التعليقات وكل شيء. ويُخزَّن كما ألصقته بالضبط: إعادة تشكيل ملف يوشك yt-dlp أن يقرأه هي الطريق إلى ملف يعمل في أداة ولا يعمل في الأخرى.',
  'cookies.useStoredHint': 'مفتاح واحد للنسخة كلها، لا لهذا الرابط: إن كان مطفأً فلا يذهب ملف محفوظ إلى أي مكان، وإلصاق واحد هنا لا يغيّر شيئًا. وهو يخصّ ما يفعله الحفظ ولا يعرض القيمة الحالية، فأنت ترى ما ستتركه هذه النافذة وراءها. وهو مفتاح لا تصرّف تلقائي، لأن الجلسة المسجَّلة الدخول لها عواقب: الحد أو الحظر يقع على الحساب لا على العنوان.',
  'select.hidden': 'منها {n} غير ظاهر',
  'select.hiddenTip': 'التحديد يضم أيضًا صفوفًا يخفيها الآن البحث أو مرشّح أو حزمة مطوية، وزر Del يأخذها معه. انقر على الرقم فلا تبقى إلا الصفوف التي تراها.',
  'select.reduceKeep': 'الإبقاء على الصفوف الظاهرة فقط',
  'select.reduceKeepAria': '{n} من الصفوف المحدّدة غير ظاهرة. انقر للإبقاء على الظاهرة فقط.',
  'select.reduceRemove': 'إزالة الصفوف الظاهرة فقط',
