  'settings.transfer.cardTitle': 'النسخ الاحتياطي والنقل',
  'settings.transfer.cardHint': 'كلا الملفين يُكتبان هنا ويحفظهما متصفحك، وهما لا يذهبان إلى أي مكان آخر. ولا يحمل أي منهما بيانات دخولك إلى خدمات debrid والمستضيفين، ولا ملفات الترويسات، ولا مفاتيح الكابتشا، ولا كلمة مرور الدخول إلى هذه الواجهة، ولا سكربتاتك: تلك تقيم معمّاة خارج settings.json، والأرشيف يتركها هو الآخر، فتعيد إعدادها على الجهاز الجديد.',
  'settings.transfer.archiveLabel': 'التثبيت بالكامل',
  'settings.transfer.archiveText': 'أرشيف واحد يضم كل ما على هذا الجهاز: قاعدة البيانات، وقائمة التنزيلات، والسجل، والإعدادات، بما فيها كلمات المرور، فاحتفظ بالملف في مكان خاص. والاستعادة تحل محل ذلك كله وتسري عند بدء التشغيل التالي.',
  'settings.transfer.settingsLabel': 'الإعدادات فقط',
  'settings.transfer.settingsText': 'ملف settings.json وحده: حدود الطابور، والمجلدات، والقواعد، والفئات، والجدول الزمني. وعند الاستيراد ترى كل مفتاح أولًا، ولا يُكتب إلا ما تحدده، ويسري فورًا دون إعادة تشغيل.',
  'settings.transfer.export': 'تصدير الإعدادات',
  'settings.transfer.import': 'استيراد الإعدادات',
  'settings.transfer.withSecrets': 'أخذ كلمات المرور المحفوظة معها',
  'settings.transfer.withSecretsHint': 'مشغّل: يحمل الملف كلمة مرور الموجّه، وكل كلمة مرور وكيل، وكل كلمة مرور أرشيف، نصًّا صريحًا. مطفأ: تصل هذه الحقول فارغة على الجهاز الآخر وتكتبها هناك مرة واحدة. وفي الحالتين قد يبقى سرّ واقفًا في مكان لا يعرفه أحد هنا: عنوان خلاصة فيه مفتاح API، أو كلمة مرور كتبتها في سكربت إعادة اتصال.',
