  'settings.selftest.jd.missing': 'لا يوجد عنوان للخلفية. تُرفض روابط DLC وروابط الحاويات المشفّرة.',
  'settings.selftest.jd.missingAdvice': 'هذا البناء يبدأ عادةً JDownloader بلا واجهة خاصًّا به أثناء الإقلاع ويملأ KL_JD بنفسه. وكونه فارغًا يعني أن ذلك البدء أخفق. ابحث عن "JD provisioning failed" في السجل أدناه، أو اضبط KL_JD على JDownloader خاص بك.',
  'settings.selftest.jd.unreachable': '{address} لم يجب.',
  'settings.selftest.jd.unreachableAdvice': 'العنوان مخزَّن ولا شيء ينصت عليه. تحقق من أن الخلفية تعمل، وأن منفذها 3128 يمكن الوصول إليه من داخل هذه الحاوية، لا من المضيف فقط.',
  'settings.selftest.jd.noVersion': 'يجيب، لكنه لا يقول أي مراجعة هو.',
  'settings.selftest.ytdlp': 'yt-dlp',
  'settings.selftest.ytdlp.ok': '{version}، وعمره {days} يومًا.',
  'settings.selftest.ytdlp.aging': '{version} عمره {days} يومًا.',
  'settings.selftest.ytdlp.old': '{version} عمره {days} يومًا. ومواقع الفيديو الكبيرة تكسره عادةً في غضون أسابيع.',
  'settings.selftest.ytdlp.oldAdvice': 'في الحاوية يأتي yt-dlp من حزمة Alpine التي كانت حديثة وقت بناء الصورة، وهو لا يحدّث نفسه أبدًا. اسحب صورة أحدث، أو ركّب yt-dlp خاصًّا بك داخل الحاوية واجعل KL_YTDLP يشير إليه.',
  'settings.selftest.ytdlp.missing': 'غير موجود، ولذلك تفشل صفحات الوسائط بخطأ المستضيف نفسه بدلًا من ذلك.',
  'settings.selftest.ytdlp.missingAdvice': 'اجعل KL_YTDLP يشير إلى الملف التنفيذي، أو ضع yt-dlp في PATH. والبحث عنه يقع مرة واحدة أثناء الإقلاع، فما يُثبَّت الآن لا يُستعمل إلا بعد إعادة تشغيل.',
  'settings.selftest.ytdlp.undated': '{version} لا يبدو تاريخًا، فلا يمكن الحكم على عمره.',
  'settings.selftest.folders': 'مجلد التنزيل ومجلد العمل',
  'settings.selftest.folders.allOk': 'كل مجلد فُحص موجود ويمكن الكتابة فيه.',
  'settings.selftest.folders.someBad': 'في مجلد واحد على الأقل ما يستحق النظر.',
  'settings.selftest.folders.none': 'لم يُقَس أي مجلد إطلاقًا.',
  'settings.selftest.folders.ok': 'يمكن الكتابة في {dir}، وفيه {free} حرة.',
  'settings.selftest.folders.notWritable': 'لا يمكن الكتابة في {dir}.',
  'settings.selftest.folders.notWritableAdvice': 'هذه العملية تعمل بالمعرّف uid {uid}. انظر مَن يملك ذلك المجلد على المضيف وهل يجوز لهذا المعرّف أن يكتب فيه.',
  'settings.selftest.folders.missing': '{dir} غير موجود بعد، فالأرقام تصف {measured} بدلًا منه.',
  'settings.selftest.folders.missingAdvice': 'وهذا طبيعي لمجلد لم يُكتب فيه شيء بعد، وأول تنزيل ينشئه. لكن إن كان {measured} هو جذر وحدة التخزين، فالتركيب الذي توقعته غائب، والتنزيل يحطّ داخل الحاوية بدل قرصك.',
  'settings.selftest.folders.low': 'لم يبقَ على {dir} إلا {free}، تحت {mark} التي يتوقف عندها الطابور.',
  'settings.selftest.folders.noMark': 'على {dir} مساحة حرة قدرها {free}. ولم تضبط حدًّا ثابتًا، فالطابور لا يحتجز تنزيلًا إلا حين لا يسعه المكان أصلًا.',
  'settings.selftest.folders.unknown': 'هذه المنصة لا يمكن سؤالها كم من المساحة على {dir}.',
  'settings.selftest.accounts': 'بيانات دخول debrid',
  'settings.selftest.accounts.none': 'لا حساب debrid مُعدّ، فلم يكن هناك ما يُفحص.',
  'settings.selftest.accounts.allOk': 'قُبلت كل بيانات الدخول، وعددها {n}.',
  'settings.selftest.accounts.someFailed': 'رُفض {bad} من {n} من بيانات الدخول.',
