  'settings.diagnostics.toolsMissing': 'غير موجود',
  'settings.eventTargets.problem.redirect': 'العنوان يجيب بإعادة توجيه، وهذه النسخة لا تتبعها. وكل قيمة ترويسة في هذا الصف تُعدّ سرًّا، وإعادة التوجيه إلى مضيف آخر كانت ستسلّمها إلى مَن يملك ذلك المضيف. افتح العنوان في متصفح، وانظر إلى أين يصل، واكتب ذلك العنوان هنا بدلًا منه.',
  'auth.twoFactor.title': 'المصادقة الثنائية',
  'auth.twoFactor.hint': 'رمز من ستة أرقام من تطبيق مصادقة، إضافة إلى كلمة السر. يقف إلى جانب كلمة السر ولا يحل محلها أبدًا. هذه النسخة ليس فيها حسابات مستخدمين، فلا أحد آخر يستطيع فتحها نيابة عنك: احفظ رموز الاسترداد في مكان غير الهاتف الذي يولد الرموز. إذا ضاع الاثنان، شغّل على الجهاز knightloader -reset-2fa، أو أوقف KnightLoader واحذف المدخلين totp و recovery من ملف auth.json في مجلد البيانات. كلمة السر تبقى تعمل في الحالتين.',
