  'auth.passkey.hint': 'مفتاح يحفظه هاتفك أو حاسوبك المحمول أو مفتاح الأمان يدخلك دون كتابة كلمة السر. هذا طريق دخول إضافي: كلمة السر تبقى صالحة، وإزالة كل مفاتيح المرور لا تحبس أحدًا في الخارج. مفتاح المرور يخص عنوان الويب الذي أُنشئ عليه، فالمفتاح المسجل عبر وسيط لا يعمل على عنوان الشبكة المحلية، والعكس كذلك.',
