  'auth.passkey.unavailableTitle': 'مفاتيح المرور تحتاج اسم مضيف، وهذه الصفحة مفتوحة على عنوان IP.',
  'auth.passkey.unavailableReason': 'مفتاح المرور مرتبط بنطاق، لذلك ترفض المتصفحات التبادل كله على عنوان عارٍ، وترفضه مرة أخرى مع شهادة لا تثق بها. صِل إلى KnightLoader عبر وسيط عكسي باسم حقيقي وشهادة صالحة، افتحه هناك، وسجّل المفتاح على ذلك العنوان.',
