  'settings.stall.reconnect': 'فتح اتصالات جديدة لتنزيل واقف',
  'settings.stall.reconnectHint': 'يغلق اتصالات تنزيل مُعلَّم ويفتح اتصالات جديدة تطلب بقية الملف. يحتفظ التنزيل بما جلبه ويحتفظ بمكانه، لذلك يبقى هذا مفعّلًا حتى تطفئه. الخادم الذي لا يستطيع إرسال الملف إلا كاملًا يرسله من جديد من البداية. من دون هذا يبقى التنزيل الذي يتوقف خادمه عن الرد في منتصف الملف على 0 B/s حتى يوقفه أحد مؤقتًا. ما دام التنزيل واقفًا يتكرر هذا كلما انقضى الوقت المحدد أعلاه. إذا كان «إعادة بدء التنزيل الواقف من أوله» مفعّلًا أيضًا، يبدأ التنزيل الذي يظل واقفًا المدة نفسها بعد الاتصالات الجديدة من أوله. تحصل على اتصالات جديدة تنزيلات المحرك المدمج وحدها، ومنها تنزيلات debrid وTorBox. يعتني JDownloader وyt-dlp باتصالاتهما بنفسيهما، والاتصالات الجديدة لا تفيد تورنت بلا نظراء، لذا تُعلَّم هذه فقط.',
  'props.backend': 'الخدمة',
  'props.backendAuto': 'تلقائي',
  'props.backendHint': 'أي خدمة تنزّل هذه الروابط. «تلقائي» يأخذ أول خدمة في ترتيب الأولوية في صفحة الحسابات تستطيع قبول الرابط الآن. الرابط المثبّت يذهب إلى تلك الخدمة وحدها ويفشل مع ذكر السبب حين لا تستطيع الخدمة قبوله. التنزيل الجاري يبقى مع خدمته. والمتوقف مؤقتًا ينتقل حين تستأنفه ويبدأ هناك من البداية.',
