  'columns.variant.convertTo': 'تحويل إلى',
  'settings.browsertools.desktopArchHint': 'لكل من Windows وLinux إصداران: x64 لمعظم الحواسيب وARM64 للحواسيب ذات معالج ARM، مثل الحواسيب المحمولة بشريحة Snapdragon. إذا أخبر المتصفح بنوع معالج هذا الحاسوب، فإن البلاطات تعطي الإصدار المناسب، وإلا فإصدار x64. الأزرار المجاورة تعطي الآخر. تطبيق macOS يعمل على Intel وعلى Apple silicon.',
  'settings.resolvers.presetFormatsUnknown': 'لا يعرف KnightLoader بعد ما الصيغ التي يقدمها {host}، لذا تعرض القوائم كل الصيغ. بمجرد فحص رابط من {host} تعرض الصيغ الموجودة في الروابط المفحوصة حتى الآن، وتسرد قائمة الصوت تحتها الصيغ الأخرى التي يمكن التحويل إليها.',
  'settings.transfer.colArrives': 'يُعتمد بوصفه',
